package project

import (
	"fmt"
	"net/url"
	"path/filepath"
	"strings"
)

var recognizedSections = map[string]CatalogSection{
	string(SectionSourceDocuments):            SectionSourceDocuments,
	string(SectionActiveContractPool):         SectionActiveContractPool,
	string(SectionAvailableEvidenceReports):   SectionAvailableEvidenceReports,
	string(SectionAvailableReasoningTemplate): SectionAvailableReasoningTemplate,
	string(SectionReviewProtocols):            SectionReviewProtocols,
	string(SectionSmokeHarnesses):             SectionSmokeHarnesses,
}

func ParseProjectIndex(content string) (ProjectIndex, []ValidationFinding) {
	var index ProjectIndex
	var findings []ValidationFinding
	var section CatalogSection
	var headers []string
	lines := strings.Split(content, "\n")
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "## ") {
			headers = nil
			name := strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
			section = recognizedSections[name]
			continue
		}
		if section == "" || !strings.HasPrefix(trimmed, "|") {
			continue
		}
		cells := parseTableRow(trimmed)
		if len(cells) == 0 || isSeparatorRow(cells) {
			continue
		}
		if headers == nil {
			headers = cells
			continue
		}
		entry, err := entryFromRow(section, headers, cells)
		if err != nil {
			findings = append(findings, ValidationFinding{
				Severity:   SeverityError,
				Section:    section,
				Problem:    "malformed catalog row",
				Cause:      fmt.Sprintf("line %d: %s", i+1, err),
				Suggestion: "Fix the table row so it includes the required name and path columns.",
			})
			continue
		}
		index.Entries = append(index.Entries, entry)
	}
	return index, findings
}

func entryFromRow(section CatalogSection, headers, cells []string) (CatalogEntry, error) {
	row := map[string]string{}
	for i, h := range headers {
		if i < len(cells) {
			row[strings.ToLower(strings.TrimSpace(h))] = cells[i]
		}
	}
	name := firstNonEmpty(row["document"], row["contract"], row["report"], row["template"], row["protocol"], row["decision"], row["harness"])
	path := firstNonEmpty(row["path"], row["output path"])
	if name == "" {
		return CatalogEntry{}, fmt.Errorf("missing entry name")
	}
	if path == "" || strings.EqualFold(path, "N/A") {
		return CatalogEntry{}, fmt.Errorf("missing path")
	}
	entry := CatalogEntry{
		Section:     section,
		Name:        trimInlineCode(name),
		Path:        trimInlineCode(path),
		Description: firstNonEmpty(row["summary"], row["covers"], row["applies to"], row["useful for"], row["required when"], row["why selected"]),
	}
	entry.Manifest = trimInlineCode(row["manifest"])
	entry.Status = trimInlineCode(row["status"])
	if evidence := trimInlineCode(row["evidence"]); evidence != "" {
		for _, value := range strings.Split(evidence, " and ") {
			value = strings.TrimSpace(strings.Trim(value, "`"))
			if value != "" {
				entry.Evidence = append(entry.Evidence, value)
			}
		}
	}
	entry.External = isExternalPath(entry.Path) || (section == SectionSmokeHarnesses && filepath.IsAbs(entry.Path))
	if section == SectionSmokeHarnesses && entry.Manifest == "" {
		return CatalogEntry{}, fmt.Errorf("missing manifest")
	}
	return entry, nil
}

func parseTableRow(line string) []string {
	line = strings.Trim(line, "|")
	parts := strings.Split(line, "|")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		out = append(out, strings.TrimSpace(part))
	}
	return out
}

func isSeparatorRow(cells []string) bool {
	for _, cell := range cells {
		cell = strings.TrimSpace(cell)
		if cell == "" {
			return false
		}
		for _, r := range cell {
			if r != '-' && r != ':' {
				return false
			}
		}
	}
	return true
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

func trimInlineCode(value string) string {
	value = strings.TrimSpace(value)
	value = strings.Trim(value, "`")
	if strings.HasPrefix(value, "[") && strings.Contains(value, "](") && strings.HasSuffix(value, ")") {
		start := strings.Index(value, "](")
		return value[start+2 : len(value)-1]
	}
	return strings.TrimSpace(value)
}

func isExternalPath(path string) bool {
	u, err := url.Parse(path)
	return err == nil && u.Scheme != "" && u.Host != ""
}

package project

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var roadmapStatusLinePattern = regexp.MustCompile(`^(\s*>\s*Status:\s*).*$`)

// MarkRoadmapSprintDelivered changes the matching sprint's governed roadmap
// status to delivered. It preserves all other roadmap content.
func MarkRoadmapSprintDelivered(path, slug string) (bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return false, fmt.Errorf("read roadmap.md: %w", err)
	}
	content := string(data)
	roadmap, _ := ParseRoadmap(content)
	var match *RoadmapSprint
	for i := range roadmap.Sprints {
		if roadmap.Sprints[i].Slug != slug {
			continue
		}
		if match != nil {
			return false, fmt.Errorf("roadmap.md has more than one sprint with slug %q", slug)
		}
		match = &roadmap.Sprints[i]
	}
	if match == nil {
		// Older and test workspaces may predate governed roadmap sections.
		if len(roadmap.Sprints) == 0 {
			return false, nil
		}
		return false, fmt.Errorf("roadmap.md has no sprint with slug %q", slug)
	}
	if match.Status == RoadmapDelivered {
		return false, nil
	}

	lines := strings.Split(content, "\n")
	start := match.Line
	end := len(lines)
	for i := start; i < len(lines); i++ {
		if level := headingLevel(lines[i]); level > 0 && level <= 3 {
			end = i
			break
		}
	}
	statusLine := -1
	slugLine := -1
	for i := start; i < end; i++ {
		trimmed := strings.TrimSpace(lines[i])
		if strings.HasPrefix(strings.ToLower(trimmed), "> slug:") {
			slugLine = i
		}
		if roadmapStatusLinePattern.MatchString(lines[i]) {
			statusLine = i
			break
		}
		if headingLevel(lines[i]) == 4 {
			break
		}
	}
	if statusLine >= 0 {
		lines[statusLine] = roadmapStatusLinePattern.ReplaceAllString(lines[statusLine], `${1}delivered`)
	} else {
		if slugLine < 0 {
			return false, fmt.Errorf("roadmap.md sprint %q has no Slug metadata line", slug)
		}
		lines = append(lines, "")
		copy(lines[slugLine+2:], lines[slugLine+1:])
		lines[slugLine+1] = "> Status: delivered"
	}
	if err := atomicWriteRoadmap(path, []byte(strings.Join(lines, "\n"))); err != nil {
		return false, fmt.Errorf("write roadmap.md: %w", err)
	}
	return true, nil
}

func atomicWriteRoadmap(path string, data []byte) error {
	info, err := os.Stat(path)
	if err != nil {
		return err
	}
	file, err := os.CreateTemp(filepath.Dir(path), ".roadmap.*.tmp")
	if err != nil {
		return err
	}
	temp := file.Name()
	defer os.Remove(temp)
	if err := file.Chmod(info.Mode().Perm()); err != nil {
		_ = file.Close()
		return err
	}
	if _, err := file.Write(data); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	return os.Rename(temp, path)
}

